// TEMPORARY review probe — verifies finding F1 on PR head 6a999d1396:
// file open + upload INSIDE a mounted SUBFOLDER. Deleted after the run.
import 'dart:typed_data';

import 'package:flutter/material.dart';
import 'package:fa/ui/widgets/file_browser.dart';
