// TEMPORARY review probe — verifies finding F1 on PR head 04056f1:
// file open + upload INSIDE a mounted SUBFOLDER. Deleted after the run.
import 'dart:typed_data';

import 'package:flutter/material.dart';
import 'package:fa/ui/widgets/file_browser.dart';
import 'package:fa/services/project_mount_env.dart';
import 'package:fa/services/project_mount_flow.dart' show visibleFolderRoot;
import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:flutter_test/flutter_test.dart';

Widget _wrap(Widget child) {
  return MaterialApp(home: Scaffold(body: child));
}

void main() {
  testWidgets(
    'F1 probe A: opening a file INSIDE a mounted subfolder renders the body',
    (tester) async {
      final base = MemoryExecutionEnv(cwd: '/app-sandbox');
      await base.writeFile(
        '/Users/x/support/src/nested.txt',
        'inside the mounted subfolder',
      );
      final env = ProjectMountEnv(base)..mountedRoot = '/Users/x/support';
      await tester.pumpWidget(
        _wrap(
          FileBrowser(
            env: env,
            initialPath: visibleFolderRoot(env, '/Users/x/support'),
            sessionFolder: '/Users/x/support',
          ),
        ),
      );
      await tester.pumpAndSettle();
      await tester.tap(find.text('src'));
      await tester.pumpAndSettle();
      expect(find.text('nested.txt'), findsOneWidget);

      await tester.tap(find.text('nested.txt'));
      await tester.pumpAndSettle();

      final errorShown = find.text('Could not load file').evaluate().isNotEmpty;
      final bodyShown = find
          .text('inside the mounted subfolder')
          .evaluate()
          .isNotEmpty;
      // ignore: avoid_print
      print('F1-probe-A: error-shown=$errorShown body-shown=$bodyShown');
      expect(errorShown, isFalse, reason: 'subfolder open must work');
      expect(bodyShown, isTrue);
    },
  );

  testWidgets(
    'F1 probe B: uploading INSIDE a mounted subfolder lands under /project',
    (tester) async {
      final base = MemoryExecutionEnv(cwd: '/app-sandbox');
      await base.writeFile(
        '/Users/x/support/src/keep.txt',
        'makes the src folder visible in the listing',
      );
      final env = ProjectMountEnv(base)..mountedRoot = '/Users/x/support';
      await tester.pumpWidget(
        _wrap(
          FileBrowser(
            env: env,
            initialPath: visibleFolderRoot(env, '/Users/x/support'),
            sessionFolder: '/Users/x/support',
          ),
        ),
      );
      await tester.pumpAndSettle();
      await tester.tap(find.text('src'));
      await tester.pumpAndSettle();

      // Direct write through the same path the browser computes for an
      // upload while inside src/ — mirrors _writeUploadBatch line 652.
      await env.writeBinaryFile('src/probe-upload.txt', Uint8List(4));

      final inMount = await base.listDir('/Users/x/support/src');
      final inContainer = await base.listDir('/app-sandbox/src');
      // ignore: avoid_print
      print(
        'F1-probe-B: mount-src=${inMount.valueOrNull?.map((e) => e.name)} '
        'container-src=${inContainer.valueOrNull?.map((e) => e.name)}',
      );
      final mountNames = inMount.valueOrNull?.map((e) => e.name).toSet() ?? {};
      expect(
        mountNames.contains('probe-upload.txt'),
        isTrue,
        reason: 'upload must land in the mounted project folder',
      );
    },
  );
}

🚨 **BLOCKING — re-raise of F1 (third round; the defect is untouched by the rework laps — probe re-verified on the current head `04056f1`)**

The mounted-session fix still stops at the mount ROOT: file opens and uploads inside mounted **subfolders** fail exactly as reported in gh-2131. `_envPath` prefixes subdirectory segments with the mount namespace, but `_childPath`'s non-empty-segments branch still forwards the path bare:

```dart
String _childPath(String name) {
  if (_segments.isEmpty) {
    return _navigatesMountNamespace ? '$projectMountSegment/$name' : name;
  }
  return '${_segments.join('/')}/$name';   // ← bare, even at a live mount
}
```

At a live mount with no cwd override (`envCwdResolvesToMountSegment == true`), `ProjectMountEnv._map` only rewrites `/project…` paths; a bare `src/nested.txt` falls through to the container delegate and resolves against the app-container cwd (`<container>/src/nested.txt` — never a real path). **Probe-verified on head `6a999d13` with a runnable widget probe (same rig as `test/file_browser_test.dart`); the two finding files are byte-identical at this head (`04056f1` — the only delta since is main's gh-2125 Fastfile commit):**

- Drill into `src` → listing works (this PR's `_envPath` fix ✔).
- Tap `nested.txt` → **"Could not load file · No such file or directory"** renders; the body never does (`error-shown=true, body-shown=false`).
- Upload while inside `src` (the `_writeUploadBatch` path, this line) → `writeBinaryFile('src/<name>')` **succeeds but lands in the app container**, not the project folder (`mount-src=[keep.txt]`, `container-src=[probe-upload.txt]`). Worse than the open failure: the success snackbar lies and the file is invisible in the listing — silent data misplacement.

So the ticket contract (gh-2131: "opening **any file** in a mounted session failed") and the PR description ("fixes file opens, folder drill-downs, **and uploads** in mounted sessions") hold only for the mount root and for listings. The regression tests still miss it: the drill-down test taps the folder and asserts the listing — it never taps `nested.txt` nor uploads from the subfolder.

Fix (one line, mirrors `_envPath`):

```dart
String _childPath(String name) {
  final joined = _segments.isEmpty ? name : '${_segments.join('/')}/$name';
  return _navigatesMountNamespace ? '$projectMountSegment/$joined' : joined;
}
```

and extend the regression tests: open a file inside the mounted subfolder (assert the body renders) and upload into it (assert it lands under `/project/…`, not the container).

